function f = objective_function(theta)
    global target_pos joint_inertia joint_avg_speed;

    [end_pos, ~] = forward_kinematics(theta);
    position_error = norm(end_pos - target_pos);

    % 假设质量集中在末端，且 z 坐标以同一高度基准计量
    mass = 5;
    g = 9.81;
    gravitational_energy = mass * g * end_pos(3);

    % 保留原代码的关节项；其物理意义和单位需按实际能耗模型确认
    joint_energy = sum(joint_inertia .* (joint_avg_speed .* theta).^2);

    f = [position_error, joint_energy + gravitational_energy];
end
```

```matlab
function disp_results(x, fval)
    [minError, minErrorIdx] = min(fval(:,1));
    [~, maxEnergyIdx] = max(fval(:,2));

    disp('最高能耗点 - 关节角度 (度):');
    disp(array2table(rad2deg(x(maxEnergyIdx,:)), ...
        'VariableNames', {'Joint1','Joint2','Joint3','Joint4','Joint5','Joint6'}));
    disp('最高能耗点 - 目标函数值:');
    disp(array2table(fval(maxEnergyIdx,:), ...
        'VariableNames', {'EndEffectorError_mm_','EnergyConsumption_J_'}));

    disp('最低误差点 - 关节角度 (度):');
    disp(array2table(rad2deg(x(minErrorIdx,:)), ...
        'VariableNames', {'Joint1','Joint2','Joint3','Joint4','Joint5','Joint6'}));
    disp('最低误差点 - 目标函数值:');
    disp(array2table(fval(minErrorIdx,:), ...
        'VariableNames', {'EndEffectorError_mm_','EnergyConsumption_J_'}));

    % 在误差不超过最低误差 1.1 倍的候选方案中，选能耗最低者
    balancedIdx = find(fval(:,1) <= 1.1 * minError);
    if ~isempty(balancedIdx)
        [~, localIdx] = min(fval(balancedIdx,2));
        bestIdx = balancedIdx(localIdx);

        disp('均衡点 - 关节角度 (度):');
        disp(array2table(rad2deg(x(bestIdx,:)), ...
            'VariableNames', {'Joint1','Joint2','Joint3','Joint4','Joint5','Joint6'}));
        disp('均衡点 - 目标函数值:');
        disp(array2table(fval(bestIdx,:), ...
            'VariableNames', {'EndEffectorError_mm_','EnergyConsumption_J_'}));
    else
        disp('未找到均衡点。');
    end
end
```

原程序按“误差优先、误差相同时再比较能耗”选全局结果，这是一种人为的决策规则；多目标优化本身通常会得到 Pareto 解集，并不存在唯一的“全局最优解”。另外，`joint_avg_speed .* theta` 的物理单位和能耗含义需要根据实际模型核实；上面的修改主要修复代码错误，并保留了原有的关节能耗表达式。

